// HasBatch applies the HasEdge predicate on the "batch" edge.
func HasBatch() predicate.AIUsageOutbox {
	return predicate.AIUsageOutbox(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, BatchTable, BatchColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasBatchWith applies the HasEdge predicate on the "batch" edge with a given conditions (other predicates).
func HasBatchWith(preds ...predicate.AIUsageBatch) predicate.AIUsageOutbox {
	return predicate.AIUsageOutbox(func(s *sql.Selector) {
		step := newBatchStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.AIUsageOutbox) predicate.AIUsageOutbox {
	return predicate.AIUsageOutbox(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.AIUsageOutbox) predicate.AIUsageOutbox {
	return predicate.AIUsageOutbox(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.AIUsageOutbox) predicate.AIUsageOutbox {
	return predicate.AIUsageOutbox(sql.NotPredicates(p))
}
